using CareComply.Api.Authorization;using CareComply.Api.Contracts.Clients;using CareComply.Application.Abstractions.Clients;using CareComply.Application.Authorization;using CareComply.Application.Features.ClientHospitalizations;using Mediator;using Microsoft.AspNetCore.Mvc;
namespace CareComply.Api.Controllers;
[ApiController,Route("api/clients/{clientId:guid}/hospitalizations")]
public sealed class ClientHospitalizationsController(ISender sender):ControllerBase{
[HttpGet,HasPermission(Permissions.ClientHospitalization.View)]public async Task<ActionResult<IReadOnlyList<ClientHospitalizationResponse>>> List(Guid clientId,CancellationToken ct){var r=await sender.Send(new ListClientHospitalizationsQuery(clientId),ct);if(r.AuthorizationFailure is not null)return Forbid();return r.List is null?NotFound():Ok(r.List.Items.Select(Map));}
[HttpPost,HasPermission(Permissions.ClientHospitalization.Create)]public async Task<ActionResult<ClientHospitalizationResponse>> Create(Guid clientId,SaveClientHospitalizationRequest x,CancellationToken ct)=>Result(await sender.Send(new SaveClientHospitalizationCommand(clientId,null,x.HospitalName,x.AdmittedAtUtc,x.DischargedAtUtc,x.Reason,x.Diagnosis,x.DischargeInstructions,null),ct),true);
[HttpPut("{id:guid}"),HasPermission(Permissions.ClientHospitalization.Edit)]public async Task<ActionResult<ClientHospitalizationResponse>> Update(Guid clientId,Guid id,SaveClientHospitalizationRequest x,CancellationToken ct)=>Result(await sender.Send(new SaveClientHospitalizationCommand(clientId,id,x.HospitalName,x.AdmittedAtUtc,x.DischargedAtUtc,x.Reason,x.Diagnosis,x.DischargeInstructions,x.EditorVersion),ct),false);
private ActionResult<ClientHospitalizationResponse> Result(HospitalizationResult r,bool created)=>r.Mutation?.Status switch{HospitalizationMutationStatus.Succeeded when r.Mutation.Value is{} x=>created?StatusCode(201,Map(x)):Ok(Map(x)),HospitalizationMutationStatus.ClientNotFound=>NotFound(),HospitalizationMutationStatus.NotFound=>NotFound(),_=>Conflict()};
private static ClientHospitalizationResponse Map(HospitalizationItem x)=>new(x.Id,x.HospitalName,x.AdmittedAtUtc,x.DischargedAtUtc,x.Reason,x.Diagnosis,x.DischargeInstructions,x.DischargedAtUtc.HasValue?"Discharged":"Admitted",x.EditorVersion);}
